    policyId: string;
    selector: VisibilityPolicySelector;
    mode: 'STATIC' | 'DYNAMIC';
    effect: 'ALLOW' | 'DENY';
    subject: {
        kind: 'PRINCIPAL';
        principalId: string;
    } | {
        kind: 'WORKLOAD';
        workloadId: string;
    };
